import{_ as n,a0 as p,w as d,s as o,ao as c,I as l,x as a,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"bc : 一個命令列計算器 | LCTT x X-CMD","titleTemplate":false,"description":"bc : 一個命令列計算器 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"bc : 一個命令列計算器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"bc : 一個命令列計算器 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160715 bc - Command line calculator","title":"bc : 一個命令列計算器","tag":"201608","desc":""},"relativePath":"201608/20160715 bc - Command line calculator.md","filePath":"[post].md"}'),h={name:"201608/20160715 bc - Command line calculator.md"};function r(b,s,g,k,u,f){const e=p("Link");return d(),o("div",null,[s[13]||(s[13]=c(`<h1 id="bc-一個命令列計算器" tabindex="-1">bc : 一個命令列計算器 <a class="header-anchor" href="#bc-一個命令列計算器" aria-label="Permalink to “bc : 一個命令列計算器”">​</a></h1><p><img src="https://cdn.fedoramagazine.org/wp-content/uploads/2016/07/bc-calculator-945x400.jpg" alt=""></p><p>假如你在一個圖形桌面環境中需要一個計算器時，你可能只需要一路進行點擊便可以找到一個計算器。例如，Fedora 工作站中就已經包含了一個名為 <code>Calculator</code> 的工具。它有着幾種不同的操作模式，例如，你可以進行復雜的數學運算或者金融運算。但是，你知道嗎，命令列也提供了一個與之相似的名為 <code>bc</code> 的工具？</p><p><code>bc</code> 工具可以為你提供的功能可以滿足你對科學計算器、金融計算器或者是簡單計算器的期望。另外，假如需要的話，它還可以從命令列中被腳本化。這使得當你需要做複雜的數學運算時，你可以在 shell 腳本中使用它。</p><p>因為 bc 也被用於其他的系統軟件，例如 CUPS 打印服務，所以它可能已經在你的 Fedora 系統中被安裝了。你可以使用下面這個命令來進行檢查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf list installed bc</span></span></code></pre></div><p>假如因為某些原因你沒有在上面命令的輸出中看到它，你可以使用下面的這個命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install bc</span></span></code></pre></div><h3 id="用-bc-做一些簡單的數學運算" tabindex="-1">用 bc 做一些簡單的數學運算 <a class="header-anchor" href="#用-bc-做一些簡單的數學運算" aria-label="Permalink to “用 bc 做一些簡單的數學運算”">​</a></h3><p>使用 bc 的一種方式是進入它自己的 shell。在那裏你可以按行進行許多次計算。當你鍵入 bc 後，首先出現的是有關這個程序的警告：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bc</span></span>
<span class="line"><span>bc 1.06.95</span></span>
<span class="line"><span>Copyright 1991-1994, 1997, 1998, 2000, 2004, 2006 Free Software Foundation, Inc.</span></span>
<span class="line"><span>This is free software with ABSOLUTELY NO WARRANTY.</span></span>
<span class="line"><span>For details type \`warranty&#39;.</span></span></code></pre></div><p>現在你可以按照每行一個輸入運算式或者命令了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1+1</span></span></code></pre></div><p>bc 會回答上面計算式的答案是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2</span></span></code></pre></div><p>在這裏你還可以執行其他的命令。你可以使用 加（+）、減（-）、乘（*）、除（/）、圓括號、指數符號（^） 等等。請注意 bc 同樣也遵循所有約定俗成的運算規則，例如運算的先後順序。你可以試試下面的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(4+7)*2</span></span>
<span class="line"><span>4+7*2</span></span></code></pre></div><p>若要退出 bc 可以通過按鍵組合 <code>Ctrl+D</code> 來發送 “輸入結束”信號給 bc 。</p><p>使用 bc 的另一種方式是使用 <code>echo</code> 命令來傳遞運算式或命令。下面這個示例就是計算器中的 “Hello, world” 例子，使用 shell 的管道函數（|） 來將 <code>echo</code> 的輸出傳入 <code>bc</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;1+1&#39; | bc</span></span></code></pre></div><p>使用 shell 的管道，你可以發送不止一個運算操作，你需要使用分號來分隔不同的運算。結果將在不同的行中返回。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;1+1; 2+2&#39; | bc</span></span></code></pre></div><h3 id="精度" tabindex="-1">精度 <a class="header-anchor" href="#精度" aria-label="Permalink to “精度”">​</a></h3><p>在某些計算中，bc 會使用精度的概念，即小數點後面的數字位數。默認的精度是 0。除法操作總是使用精度的設定。所以，如果你沒有設置精度，有可能會帶來意想不到的答案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;3/2&#39; | bc</span></span>
<span class="line"><span>echo &#39;scale=3; 3/2&#39; | bc</span></span></code></pre></div><p>乘法使用一個更復雜的精度選擇機制：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;3*2&#39; | bc</span></span>
<span class="line"><span>echo &#39;3*2.0&#39; | bc</span></span></code></pre></div><p>同時，加法和減法的相關運算則與之相似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;7-4.15&#39; | bc</span></span></code></pre></div><h3 id="其他進制系統" tabindex="-1">其他進制系統 <a class="header-anchor" href="#其他進制系統" aria-label="Permalink to “其他進制系統”">​</a></h3><p>bc 的另一個有用的功能是可以使用除了十進制以外的其他計數系統。例如，你可以輕鬆地做十六進制或二進制的數學運算。可以使用 <code>ibase</code> 和 <code>obase</code> 命令來分別設定輸入和輸出的進制系統。需要記住的是一旦你使用了 <code>ibase</code>，之後你輸入的任何數字都將被認為是在新定義的進制系統中。</p><p>要做十六進制數到十進制數的轉換或運算，你可以使用類似下面的命令。請注意大於 9 的十六進制數必須是大寫的（A-F）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;ibase=16; A42F&#39; | bc</span></span>
<span class="line"><span>echo &#39;ibase=16; 5F72+C39B&#39; | bc</span></span></code></pre></div><p>若要使得結果是十六進制數，則需要設定 <code>obase</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;obase=16; ibase=16; 5F72+C39B&#39; | bc</span></span></code></pre></div><p>下面是一個小技巧。假如你在 shell 中做這些十六進制運算，怎樣才能使得輸入重新為十進制數呢？答案是使用 <code>ibase</code> 命令，但你必須設定它為在當前進制中與十進制中的 10 等價的值。例如，假如 <code>ibase</code> 被設定為十六進制，你需要輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ibase=A</span></span></code></pre></div><p>一旦你執行了上面的命令，所有輸入的數字都將是十進制的了，接着你便可以輸入 <code>obase=10</code> 來重置輸出的進制系統。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>上面所提到的只是 bc 所能做到的基礎。它還允許你為某些複雜的運算和程序定義函數、變量和循環結構。你可以在你的系統中將這些程序保存為文本文件以便你在需要的時候使用。你還可以在網上找到更多的資源，它們提供了更多的例子以及額外的函數庫。快樂地計算吧！</p><hr>`,41)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/bc-command-line-calculator/"},{default:t(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/bc-command-line-calculator/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/pfrields/"},{default:t(()=>[...s[2]||(s[2]=[a("Paul W. Frields",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),i(e,{href:"https://github.com/FSSlc"},{default:t(()=>[...s[3]||(s[3]=[a("FSSlc",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const x=n(h,[["render",r]]);export{y as __pageData,x as default};
